import React, { useEffect, useState } from "react";
import axios from "axios";

const API_URL = "http://localhost:5000/api";

function AdminPanel({
  candidateForm,
  setCandidateForm,
  onSave,
  editId,
  setEditId,
  onDelete,
  candidates,
  theme,
}) {
  const [codes, setCodes] = useState([]);
  const [selectedCourse, setSelectedCourse] = useState("");

  const [stats, setStats] = useState({
    totalVoterCodes: 0,
    usedCodes: 0,
    totalVotes: 0,
    turnout: 0,
  });

  const token = localStorage.getItem("token");

  const authHeader = {
    headers: { Authorization: `Bearer ${token}` },
  };

  // ======================
  // FETCH CODES
  // ======================
  const fetchCodes = async () => {
    try {
      const res = await axios.get(`${API_URL}/codes`, authHeader);
      setCodes(res.data);
    } catch (error) {
      console.error("Error fetching codes:", error);
    }
  };

  // ======================
  // FETCH STATS (FIXED)
  // ======================
  const fetchStats = async () => {
    try {
      const res = await axios.get(`${API_URL}/stats`, authHeader);
      setStats(res.data);
    } catch (error) {
      console.error("Error fetching stats:", error);
    }
  };

  // ======================
  // REFRESH ALL (FIXED)
  // ======================
  const refreshAll = async () => {
    await Promise.all([fetchCodes(), fetchStats()]);
  };

  useEffect(() => {
    refreshAll();
  }, []);

  // ======================
  // GENERATE CODES
  // ======================
  const generateCodes = async () => {
    const amount = prompt("Enter number of voter codes to generate:");

    if (!amount || isNaN(amount)) {
      alert("Please enter a valid number.");
      return;
    }

    try {
      await axios.post(
        `${API_URL}/codes/generate`,
        { amount: Number(amount) },
        authHeader
      );

      await refreshAll();
      alert(`${amount} voter codes generated successfully.`);
    } catch (error) {
      console.error(error);
      alert("Failed to generate codes.");
    }
  };

  // ======================
  // DELETE CODE
  // ======================
  const deleteCode = async (id) => {
    if (!window.confirm("Delete this voter code?")) return;

    try {
      await axios.delete(`${API_URL}/codes/${id}`, authHeader);
      await refreshAll();
    } catch (error) {
      alert("Failed to delete voter code.");
    }
  };

  // ======================
  // RESET ELECTION (FIXED)
  // ======================
  const resetElection = async () => {
    if (!window.confirm("Reset entire election? All votes will be deleted.")) return;

    try {
      const res = await axios.post(
        `${API_URL}/admin/reset-election`,
        {},
        authHeader
      );

      alert(res.data.message);

      await refreshAll();
    } catch (error) {
      console.error(error.response?.data || error.message);
      alert(error.response?.data?.message || "Failed to reset election.");
    }
  };

  // ======================
  // CANCEL EDIT
  // ======================
  const handleCancelEdit = () => {
    setCandidateForm({
      firstName: "",
      lastName: "",
      candidacy: "",
      partylist: "",
      yearLevel: "",
      block: "",
      course: "",
      description: "",
      image: null,
    });

    setEditId(null);
  };

  // ======================
  // FILTER
  // ======================
  const filteredCandidates = candidates.filter(
    (c) => !selectedCourse || c.course === selectedCourse
  );

  // ======================
  // UI
  // ======================
  return (
    <div style={containerStyle(theme)}>
      {/* ================= STATS ================= */}
      <h3 style={{ color: theme.text }}>Election Statistics</h3>

      <div style={statsContainer}>
        <StatCard title="Total Codes" value={stats.totalVoterCodes} />
        <StatCard title="Used Codes" value={stats.usedCodes} />
        <StatCard title="Votes Cast" value={stats.totalVotes} />
        <StatCard title="Turnout" value={`${stats.turnout}%`} />
      </div>

      <button onClick={resetElection} style={resetButton}>
        Reset Election
      </button>

      {/* ================= CANDIDATES ================= */}
      <h3 style={{ color: theme.text }}>Candidates</h3>

      {filteredCandidates.map((c) => (
        <div key={c._id} style={candidateCard(theme)}>
          <div>
            <strong>
              {c.firstName} {c.lastName}
            </strong>{" "}
            — {c.candidacy}
            <br />
            <small>
              {c.partylist || "Independent"} | {c.course || "No Course"}
            </small>
          </div>

          <div style={{ display: "flex", gap: 8 }}>
            <button onClick={() => setEditId(c._id)} style={editButton}>
              Edit
            </button>

            <button onClick={() => onDelete(c._id)} style={deleteButton}>
              Delete
            </button>
          </div>
        </div>
      ))}

      {/* ================= VOTER CODES ================= */}
      <h3 style={{ color: theme.text }}>Voter Codes</h3>

      <button onClick={generateCodes} style={generateButton}>
        Generate Codes
      </button>

      <table style={table}>
        <thead>
          <tr>
            <th style={tableCell}>Code</th>
            <th style={tableCell}>Status</th>
            <th style={tableCell}>Action</th>
          </tr>
        </thead>

        <tbody>
          {codes.map((c) => (
            <tr key={c._id}>
              <td style={tableCell}>{c.code}</td>
              <td style={tableCell}>{c.used ? "Used" : "Unused"}</td>
              <td style={tableCell}>
                <button onClick={() => deleteCode(c._id)} style={deleteButton}>
                  Delete
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

/* ================= STATS CARD ================= */
const StatCard = ({ title, value }) => (
  <div style={statCard}>
    <h4>{title}</h4>
    <p>{value}</p>
  </div>
);

/* ================= STYLES ================= */
const containerStyle = (theme) => ({
  padding: 20,
  borderRadius: 10,
  background: theme.card,
  display: "flex",
  flexDirection: "column",
  gap: 20,
});

const statsContainer = {
  display: "flex",
  gap: 20,
  flexWrap: "wrap",
};

const statCard = {
  background: "#f3f4f6",
  padding: 15,
  borderRadius: 8,
  minWidth: 120,
  textAlign: "center",
};

const candidateCard = (theme) => ({
  display: "flex",
  justifyContent: "space-between",
  padding: 10,
  borderRadius: 8,
  background: theme.background,
});

const resetButton = {
  background: "#ef4444",
  color: "#fff",
  border: "none",
  padding: "8px 14px",
  borderRadius: 6,
  width: 200,
};

const generateButton = {
  background: "#22c55e",
  color: "#fff",
  border: "none",
  padding: "8px 14px",
  borderRadius: 6,
};

const deleteButton = {
  background: "#ef4444",
  color: "#fff",
  border: "none",
  padding: "4px 10px",
  borderRadius: 6,
};

const editButton = {
  background: "#6366f1",
  color: "#fff",
  border: "none",
  padding: "4px 10px",
  borderRadius: 6,
};

const table = {
  width: "100%",
  borderCollapse: "collapse",
};

const tableCell = {
  border: "1px solid #ccc",
  padding: 8,
  textAlign: "center",
};

export default AdminPanel;
